@media (-moz-gtk-csd-transparency-available) {
  :root[customtitlebar] {
    background-color: transparent;

    &[sizemode="normal"]:not([tiled]) {
      /* This takes care of drawing our window decorations on X11 */
      -moz-default-appearance: -moz-window-decorations;
      appearance: auto;

      #navigation-toolbox,
      ::backdrop {
        border-start-start-radius: env(-moz-gtk-csd-titlebar-radius);
        border-start-end-radius: env(-moz-gtk-csd-titlebar-radius);
      }
